// launch-factory: 예약 서비스 조립. 순서: 요청 제한(DB) → 멱등 키 → 입력 검사 → Turnstile → 수용량 잠금 안에서 저장 → 메일(+선택 통로) 안내.
// 설정(영업시간·서비스·마감·예약금)은 lib/launch/booking-config.ts 데이터가 정한다. 예약금은 lib/launch/booking-deposit.ts 가 넘기는 훅으로 받는다(기본 없음 — feature-booking-deposit 가 채운다).
// 운영자 메일(BOOKING_OWNER_EMAIL)이 없으면 예약 접수만 꺼진다 — bookingEnabled() 가 false 이고 서비스는 접수를 provider_unavailable 로 거절한다.
import { BOOKING_RATE_RULES, createBookingService, depositOf, depositRules, parseBookingConfig, type BookingConfig, type BookingService } from "@launch-factory/booking"
import { hitRateLimit } from "@launch-factory/db"
import { createRateLimiter, ipAddressFromEnv, warnNoIpOnce } from "@launch-factory/security/rate-limit"
import { createTurnstile } from "@launch-factory/security/turnstile"
import { BOOKING_CONFIG } from "@/lib/launch/booking-config"
import { bookingDeposit } from "@/lib/launch/booking-deposit"
import { bookingNotifier } from "@/lib/launch/booking-notify"
import { appUrl, DEFAULT_LOCALE, PRODUCT_NAME } from "@/lib/launch/config"
import { database } from "@/lib/launch/db"
import { env, optional, required } from "@/lib/launch/env"
import { mailer } from "@/lib/launch/mailer"

/** 검사를 거친 설정. 틀리면 모듈을 읽을 때 던진다(켜진 척하지 않는다) */
export const bookingConfig: BookingConfig = parseBookingConfig(BOOKING_CONFIG)

/** 예약 폼이 보여 주는 서비스 한 줄. 설정 전체가 아니라 화면이 쓰는 칸만 직렬화 가능한 모양으로 낸다. 예약금 있는 서비스는 금액·대기 시간·환불 규정도 싣는다(전부 설정 값 — 브라우저는 보여 주기만 한다) */
export interface BookingServiceView {
  id: string
  name: string
  durationMin: number
  partyMax: number
  deposit?: { amount: number; holdMinutes: number; fullRefundBeforeMinutes: number; laterRefundPercent: number }
}

export function bookingServiceViews(locale: "en" = "en"): BookingServiceView[] {
  const rules = depositRules(bookingConfig)
  return bookingConfig.services.map((s) => ({
    id: s.id,
    name: s.name[locale],
    durationMin: s.durationMin,
    partyMax: s.partyMax,
    ...(depositOf(s) > 0 ? { deposit: { amount: depositOf(s), holdMinutes: rules.holdMinutes, fullRefundBeforeMinutes: rules.fullRefundBeforeMinutes, laterRefundPercent: rules.laterRefundPercent } } : {}),
  }))
}

let cached: Promise<BookingService> | undefined

export function booking(): Promise<BookingService> {
  return (cached ??= build())
}

/**
 * 새 예약 알림을 받을 운영자 메일. **없으면 예약 접수만 꺼진다**(사이트는 켜진다 — 문의 창구와 같은 규칙). mock 은 없으면 가짜 주소로 켠다 — 메일은 콘솔에만 찍힌다.
 * 운영자 확인 권한(confirm)도 이 주소의 확인된 계정이 가진다.
 */
export function bookingOwnerEmail(): string | undefined {
  return optional("BOOKING_OWNER_EMAIL") ?? (env().LF_MODE === "live" ? undefined : "owner@example.test")
}

/** 예약을 받는가. 쪽(/book)이 폼 대신 안내를 그린다. 데이터베이스에 닿지 않는다 */
export const bookingEnabled = (): boolean => bookingOwnerEmail() !== undefined

async function build(): Promise<BookingService> {
  const db = await database()
  const live = env().LF_MODE === "live"
  const ownerAddress = bookingOwnerEmail()
  const deposit = await bookingDeposit()
  return createBookingService({
    db,
    mailer: mailer(),
    limiter: createRateLimiter({ store: { hit: (key, windowMs, now) => hitRateLimit(db, key, windowMs, now) }, rules: BOOKING_RATE_RULES, ipAddress: ipAddressFromEnv(process.env), onNoIp: warnNoIpOnce() }),
    turnstile: createTurnstile(live ? { mode: "live", secretKey: required("TURNSTILE_SECRET_KEY") } : { mode: "mock" }),
    config: BOOKING_CONFIG,
    // 주소가 없으면 owner 를 빼 접수만 끈다: 이미 받은 예약의 조회·취소·알림·파기 Cron 은 그대로 된다
    ...(ownerAddress ? { owner: { email: ownerAddress, locale: DEFAULT_LOCALE } } : {}),
    productName: PRODUCT_NAME,
    manageUrl: `${appUrl()}/book/manage`,
    bookUrl: `${appUrl()}/book`,
    ...(bookingNotifier ? { notify: bookingNotifier } : {}),
    ...(deposit ? { deposit } : {}),
    onError: (e) => console.error("[booking]", e.message),
  })
}

// launch-factory: 예약 설정(계획 3b). 이 파일은 제품 것이다 — 레지스트리를 다시 받으면 덮어쓸지 묻는다.
// 영업시간·서비스·수용량·취소 마감은 코드가 아니라 이 데이터가 정한다. 모양은 @launch-factory/booking 의 BookingConfigSchema 가 켤 때 검사한다(틀리면 시작 때 던진다).
// 아래 값은 견본이다 — 제품의 서비스·시간으로 바꾼다. 서비스 하나 = id · 이름(ko·en) · 걸리는 시간 · 같은 시간에 받을 수 있는 수(capacity) · 한 예약 최대 인원.
import { bookingDepositEnabled } from "@/lib/launch/booking-deposit"

export const BOOKING_CONFIG = {
  /** IANA 시간대. 영업시간·휴무일·슬롯 날짜는 이 시간대의 달력으로 읽는다 */
  timeZone: "Asia/Seoul",
  /** "instant": 접수하면 바로 확정 · "request": 운영자이 확인(confirm)한 뒤 확정 */
  mode: "instant",
  services: [
    { id: "consultation", name: { ko: "상담", en: "Consultation" }, durationMin: 60, capacity: 1, partyMax: 1 },
    // 견본 — **mock 미리보기에서, 예약금 연결(feature-booking-deposit)이 있을 때만** 보이는 예약금 서비스(한 바퀴 시험이 결제 단계를 돈다). live 에는 나오지 않는다: 견본 서비스가 실제 결제를 일으키지 않게 한다.
    // 제품은 자기 서비스에 deposit(원)을 직접 적고 이 줄은 지운다.
    ...(process.env.LF_MODE === "mock" && bookingDepositEnabled() ? [{ id: "deposit-consultation", name: { ko: "우선 상담", en: "Priority consultation" }, durationMin: 60, capacity: 1, partyMax: 1, deposit: 10000 }] : []),
  ],
  /** 요일별 영업 구간 [시작, 끝]("HH:MM"). 없는 요일은 쉰다 */
  weekly: {
    mon: [["10:00", "18:00"]],
    tue: [["10:00", "18:00"]],
    wed: [["10:00", "18:00"]],
    thu: [["10:00", "18:00"]],
    fri: [["10:00", "18:00"]],
  },
  /** 휴무일("YYYY-MM-DD") */
  closedDates: [] as string[],
  /** 슬롯 간격(분) */
  slotStepMin: 30,
  /** 지금부터 이 시간(분) 안은 잡을 수 없다 */
  leadMinutes: 120,
  /** 오늘부터 며칠 앞까지 받는가 */
  horizonDays: 60,
  /** 시작 이 시간(분) 전까지만 예약한 사람이 직접 취소할 수 있다 */
  cancelBeforeMinutes: 120,
  /** 시작 이 시간(분) 전에 안내를 보낸다(0 이면 끔) */
  reminderBeforeMinutes: 1440,
  /** 예약 기록 보유 기간(일). 예약금 건은 서비스가 5년으로 늘린다 */
  retainDays: 365,
  // 예약금(선택). 서비스에 `deposit: 30000`(원, 정수)을 적으면 그 서비스는 접수 → 결제 대기 → 결제하면 확정이다. 0 이거나 없으면 예약금 없음.
  // 금액은 여기서만 정해진다 — 브라우저가 보낸 금액은 읽지 않는다. feature-booking-deposit(결제 중개)가 있어야 접수를 받는다.
  // 아래 규칙은 모두 선택이다(빠지면 기본값): 결제 대기 30분(결제 대기 예약도 자리를 차지한다) · 전액 환불은 취소 마감까지 · 마감 뒤 취소는 환불 없음 · 운영자가 취소하면 전액 환불(ownerCancelRefundPercent, 0~100).
  // depositPolicy: { holdMinutes: 30, fullRefundBeforeMinutes: 1440, laterRefundPercent: 50, ownerCancelRefundPercent: 100 },
}

// launch-factory: 예약 안내의 다른 통로(카카오 알림톡·문자). 기본은 없음 — 예약 확인·취소·알림은 메일로만 간다.
// feature-notify-kr 를 설치하면 이 파일을 그 항목의 것(알림톡·문자 통로)이 대신한다.
import type { BookingNotifier } from "@launch-factory/booking"

export const bookingNotifier: BookingNotifier | undefined = undefined

// launch-factory: 예약금 연결 자리. 기본은 없음 — 예약금이 있는 서비스(설정의 deposit > 0)는 이 자리가 비어 있으면 접수를 받지 않는다(provider_unavailable).
// feature-booking-deposit 를 설치하면 이 파일을 그 항목의 것(결제 중개 payments-kr 로 예약금을 받고 돌려주는 훅)이 대신한다.
import type { DepositHook } from "@launch-factory/booking"

/** 예약금을 받을 수 있는가(결제 중개가 켜져 있는가). 네트워크·DB 에 닿지 않는다 */
export const bookingDepositEnabled = (): boolean => false

export async function bookingDeposit(): Promise<DepositHook | undefined> {
  return undefined
}

// launch-factory: 예약이 세션에서 읽는 것 두 가지. 서버 전용이다(공개 서버 액션으로 열지 않는다).
//   currentUserId — 로그인했으면 그 사용자 id(예약 행·요청 제한 키에 들어간다). 로그아웃·만료·대리 로그인 세션은 null(대리 세션이 그 사람 이름으로 예약하지 못한다).
//   bookingActor  — 확정·대신 취소를 하는 사람(세션은 액션이 먼저 읽어 넘긴다). 소유자 = 확인된 이메일이 BOOKING_OWNER_EMAIL 과 같은 사람, 관리자 = user.role 에 admin. 정지된 사람은 아니다.
import { user } from "@launch-factory/db"
import { eq } from "drizzle-orm"
import type { BookingActor } from "@launch-factory/booking"
import { authPort } from "@/lib/launch/auth"
import { bookingOwnerEmail } from "@/lib/launch/booking"
import { database } from "@/lib/launch/db"

export async function currentUserId(): Promise<string | null> {
  try {
    const s = await (await authPort()).session()
    return s.ok && s.data && !s.data.impersonatedBy ? s.data.userId : null
  } catch {
    return null
  }
}

/** 세션(액션이 `authPort().session()` 으로 읽은 것)의 행위자. 정지된 사람 → null, 대리 세션 → "impersonated" */
export async function bookingActor(session: { userId: string; impersonatedBy?: string | null }): Promise<BookingActor | "impersonated" | null> {
  if (session.impersonatedBy) return "impersonated"
  const [row] = await (await database()).select({ id: user.id, role: user.role, email: user.email, emailVerified: user.emailVerified, banned: user.banned }).from(user).where(eq(user.id, session.userId)).limit(1)
  if (!row || row.banned) return null
  const owner = bookingOwnerEmail()
  return { userId: row.id, role: row.role, isOwner: Boolean(owner && row.emailVerified && row.email.toLowerCase() === owner.toLowerCase()) }
}

// launch-factory: 예약 접수 경로(POST, FormData 또는 JSON). 429 + Retry-After · 봇 400 · 칸 오류 400 · 마감 409 · 확인 불가 503 · 처리 중 409.
// 폼에 숨은 입력 둘을 더한다: Turnstile 토큰 `cf-turnstile-response`, 폼을 열 때 만든 `idempotencyKey`.
import { currentUserId } from "@/lib/launch/booking-session"
import { booking } from "@/lib/launch/booking"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function POST(request: Request) {
  return (await booking()).handler(request, { userId: await currentUserId() })
}

// launch-factory: 예약 가능 시간 조회(GET ?service=&from=YYYY-MM-DD&days=). 공개 조회라 로그인이 필요 없다.
import { toResponse } from "@launch-factory/booking"
import { booking } from "@/lib/launch/booking"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function GET(request: Request) {
  const q = new URL(request.url).searchParams
  const days = q.get("days")
  return toResponse(await (await booking()).slots({ service: q.get("service") ?? "", from: q.get("from") ?? "", ...(days ? { days: Number(days) } : {}) }))
}

// launch-factory: 예약 Cron(30분마다 권장). 시작 전 안내를 한 번만 보내고, 예약금 결제 대기 시간이 지난 예약을 닫아 자리를 풀고, 보유 기간이 지난 예약을 지운다.
// vercel.json 에 `{ "crons": [{ "path": "/api/cron/booking", "schedule": "*/30 * * * *" }] }` 를 더한다. CRON_SECRET 이 없으면 401 이다.
import { cronAuthorized, unauthorized } from "@/lib/launch/cron"
import { booking } from "@/lib/launch/booking"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function GET(request: Request) {
  if (!cronAuthorized(request)) return unauthorized()
  const service = await booking()
  return Response.json({ reminded: await service.remindDue(), expiredDeposits: await service.expireDeposits(), purged: await service.purgeExpired() })
}

"use server"
// launch-factory: 예약 서버 액션 — web-factory 예약 블록의 submit 포트 모양이다(`(input: Record<string, string>) => Promise<ActionResult>`).
// 서버 액션은 공개 경로라 입력 모양을 먼저 본다. IP 는 요청 머리에서 읽어 요청 제한 키에만 쓴다(저장하지 않는다).
import { headers } from "next/headers"
import { booking } from "@/lib/launch/booking"
import { currentUserId } from "@/lib/launch/booking-session"
import { DEFAULT_LOCALE } from "@/lib/launch/config"

const invalid = { ok: false as const, error: "invalid_input" as const }
const str = (v: unknown, max: number): string | null => (typeof v === "string" && v.length <= max ? v : null)

const ctx = async () => ({ headers: new Headers(await headers()), userId: await currentUserId(), locale: DEFAULT_LOCALE })

/** 예약 가능 시간. input: { service, from: "YYYY-MM-DD", days? } */
export async function loadBookingSlots(input: unknown) {
  if (typeof input !== "object" || input === null) return invalid
  const i = input as Record<string, unknown>
  const service = str(i.service, 64)
  const from = str(i.from, 10)
  if (!service || !from) return invalid
  const days = typeof i.days === "number" && Number.isInteger(i.days) ? i.days : undefined
  return (await booking()).slots({ service, from, ...(days ? { days } : {}) }, { locale: DEFAULT_LOCALE })
}

/** 예약 접수. input: 폼 칸(service·startsAt·partySize·name·contact·note + idempotencyKey·cf-turnstile-response) */
export async function submitBooking(input: Record<string, string>) {
  return (await booking()).action(await ctx())(input)
}

/** 예약 번호 + 연락처로 예약을 보여 준다. 틀린 조합은 모두 같은 not_found */
export async function lookupBooking(input: unknown) {
  const p = pair(input)
  return p ? (await booking()).lookup(p, await ctx()) : invalid
}

/** 예약한 사람이 직접 취소한다(취소 마감 전까지) */
export async function cancelBooking(input: unknown) {
  const p = pair(input)
  return p ? (await booking()).cancel(p, await ctx()) : invalid
}

function pair(input: unknown): { reference: string; contact: string } | null {
  if (typeof input !== "object" || input === null) return null
  const i = input as Record<string, unknown>
  const reference = str(i.reference, 64)
  const contact = str(i.contact, 254)
  return reference && contact ? { reference, contact } : null
}

// launch-factory: 관리 화면 구획 — 예약(계획 3d L2b). 서버 전용. 대상 = 운영자(BOOKING_OWNER_EMAIL 로 확인된 계정) 또는 관리자.
// 구획은 서버 액션이 아니라 예약 서비스를 직접 부른다: 콘솔이 입장시킨 행위자(actor)를 그대로 넘기면 서비스가 직원 규칙을 한 번 더 검사한다(두 겹).
// 표는 연락처를 가려서(콘솔이) 보이고, 기록 상세에는 연락처·이름·메모 전체가 든다. 직원 메모 칸은 예약 도메인에 없다(note 는 예약한 사람이 남긴 메모) — 그래서 편집 폼은 없다.
// 행동: 확정(mode "request"에서 운영자 확인을 기다리는 예약) · 취소(위험 — 결제된 예약금은 대표 취소 환불 비율(depositPolicy.ownerCancelRefundPercent, 기본 전액)대로 돌려준 뒤에만 취소되고, 환불이 실패하면 거절로 끝나 예약은 그대로 남는다).
import { defineSection, refuse, type AdminActor, type Outcome, type Refusal } from "@launch-factory/admin-console"
import type { BookingResult, BookingStaffRow } from "@launch-factory/booking"
import { booking, bookingOwnerEmail } from "@/lib/launch/booking"

const STATUSES = ["requested", "confirmed", "cancelled", "completed", "no_show"] as const
type Status = (typeof STATUSES)[number]

/** 서비스의 실패를 거절로 옮긴다 — 코드와 서비스가 쓴 안내 문구(개인정보 없음)만 나간다 */
const refusalOf = (r: Extract<BookingResult<unknown>, { ok: false }>): Refusal => refuse(r.code ?? "action_failed", r.formError !== undefined ? { formError: r.formError } : {})

/** 서비스 결과 → 행동 결과(성공이면 안내 문구, 실패면 거절) */
const outcomeOf = (r: BookingResult<{ message: string }>): Outcome => (r.ok ? { message: r.data.message } : refusalOf(r))

/** 자리를 차지하는 상태 — 취소할 수 있다(결제 대기 건은 닫기만 한다) */
const holding = (b: BookingStaffRow) => b.status === "requested" || b.status === "confirmed"
/** 운영자 확인을 기다리는 예약 — 예약금 결제를 기다리는 건은 결제가 끝나야 이어지고, 지난 시각의 요청은 확정하지 않는다 */
const confirmable = (b: BookingStaffRow, at: Date = new Date()) => b.status === "requested" && b.depositStatus !== "pending" && Date.parse(b.startsAt) > at.getTime()

const won = (n: number) => `${n.toLocaleString("en-US")} KRW`

export default defineSection({
  id: "bookings",
  part: "booking",
  label: "Bookings",
  audience: { owner: () => bookingOwnerEmail() },
  statuses: STATUSES,
  serverSearch: true, // 서버 검색: 접수 번호·연락처(메일·전화)·이름 부분 일치(listForStaff). 표의 연락처는 가려서 나가므로 화면이 다시 거르면 이메일로 찾을 수 없다
  columns: [
    { id: "reference", label: "Reference", kind: "text", primary: true },
    { id: "startsAt", label: "Starts", kind: "date", sortable: true },
    { id: "service", label: "Service", kind: "text" },
